47	    init(roomProxy: JoinedRoomProxyProtocol,
48	         timelineProxy: TimelineProxyProtocol,
49	         initialFocussedEventID: String?,
50	         timelineItemFactory: RoomTimelineItemFactoryProtocol,
51	         mediaProvider: MediaProviderProtocol,
52	         appSettings: AppSettings) {
53	        self.roomProxy = roomProxy
54	        liveTimelineItemProvider = timelineProxy.timelineItemProvider
55	        self.timelineItemFactory = timelineItemFactory
56	        self.mediaProvider = mediaProvider
57	        self.appSettings = appSettings
58	        
59	        activeTimeline = timelineProxy
60	        activeTimelineItemProvider = liveTimelineItemProvider
61	        
62	        guard let initialFocussedEventID else {
63	            configureActiveTimelineItemProvider()
64	            return
65	        }
66	        
67	        Task {
68	            paginationState = TimelinePaginationState(backward: .paginating, forward: .paginating)
69	            
70	            switch await focusOnEvent(initialFocussedEventID, timelineSize: 100) {
71	            case .success:
72	                break
73	            case .failure:
74	                // Setup the live timeline as a fallback.
75	                configureActiveTimelineItemProvider()
76	            }
77	        }
78	    }
