80	    func focusOnEvent(_ eventID: String, timelineSize: UInt16) async -> Result<Void, TimelineControllerError> {
81	        switch await roomProxy.timelineFocusedOnEvent(eventID: eventID, numberOfEvents: timelineSize) {
82	        case .success(let timeline):
83	            await timeline.subscribeForUpdates()
84	            activeTimeline = timeline
85	            activeTimelineItemProvider = timeline.timelineItemProvider
86	            return .success(())
87	        case .failure(let error):
88	            if case .eventNotFound = error {
89	                return .failure(.eventNotFound)
90	            } else {
91	                return .failure(.generic)
92	            }
93	        }
94	    }
