82	    private func updateItemsWithDiffs(_ diffs: [TimelineDiff]) {
83	        let span = MXLog.createSpan("process_timeline_list_diffs:\(kind)")
84	        span.enter()
85	        defer {
86	            span.exit()
87	        }
88	        
89	        MXLog.verbose("Received diffs: \(diffs)")
90	        
91	        itemProxies = diffs.reduce(itemProxies) { currentItems, diff in
92	            guard let collectionDiff = buildDiff(from: diff, on: currentItems) else {
93	                MXLog.error("Failed building CollectionDifference from \(diff)")
94	                return currentItems
95	            }
96	            
97	            guard let updatedItems = currentItems.applying(collectionDiff) else {
98	                MXLog.error("Failed applying diff: \(collectionDiff)")
99	                return currentItems
100	            }
101	            
102	            return updatedItems
103	        }
104	        
105	        if let hasLoadedInitialItemsContinuation {
106	            hasLoadedInitialItemsContinuation.resume()
107	            self.hasLoadedInitialItemsContinuation = nil
108	        }
109	    }
