12	/// A timeline item identifier
13	/// - uniqueID: Stable id across state changes of the timeline item, it uniquely identifies an item in a timeline.
14	/// Its value is consistent only per timeline instance, it should **not** be used to identify an item across timeline instances.
15	/// - eventOrTransactionID: Contains the 2 possible identifiers of an event, either it has a remote event id or
16	/// a local transaction id, never both or none.
17	enum TimelineItemIdentifier: Hashable {
18	    struct UniqueID: Hashable {
19	        let value: String
20	        
21	        init(_ value: String) {
22	            self.value = value
23	        }
24	        
25	        init(rustValue: TimelineUniqueId) {
26	            self.init(rustValue.id)
27	        }
28	        
29	        var rustValue: TimelineUniqueId {
30	            .init(id: value)
31	        }
32	    }
33	    
34	    enum EventOrTransactionID: Hashable {
35	        case eventID(String), transactionID(String)
36	        
37	        init(rustValue: EventOrTransactionId) {
38	            switch rustValue {
39	            case .eventId(let eventID): self = .eventID(eventID)
40	            case .transactionId(let transactionID): self = .transactionID(transactionID)
41	            }
42	        }
43	        
44	        var rustValue: EventOrTransactionId {
45	            switch self {
46	            case .eventID(let eventID): .eventId(eventId: eventID)
47	            case .transactionID(let transactionID): .transactionId(transactionId: transactionID)
48	            }
49	        }
50	    }
51	    
52	    case event(uniqueID: UniqueID, eventOrTransactionID: EventOrTransactionID)
53	    case virtual(uniqueID: UniqueID)
54	    
55	    var uniqueID: UniqueID {
56	        switch self {
57	        case .event(let uniqueID, _): uniqueID
58	        case .virtual(let uniqueID): uniqueID
59	        }
60	    }
61	    
62	    var eventOrTransactionID: EventOrTransactionID? {
63	        guard case let .event(_, eventOrTransactionID) = self else { return nil }
64	        return eventOrTransactionID
65	    }
66	    
67	    var eventID: String? {
68	        guard case let .event(_, .eventID(eventID)) = self else { return nil }
69	        return eventID
70	    }
71	    
72	    var transactionID: String? {
73	        guard case let .event(_, .transactionID(transactionID)) = self else { return nil }
74	        return transactionID
75	    }
76	}
