141	    
142	    init(model: String, originalJSON: String?, latestEditJSON: String?) {
143	        self.model = model
144	        
145	        self.originalJSON = Self.prettyJsonFormattedString(from: originalJSON)
146	        self.latestEditJSON = Self.prettyJsonFormattedString(from: latestEditJSON)
147	    }
