163	    // MARK: - Private
164	    
165	    private static func prettyJsonFormattedString(from string: String?) -> String? {
166	        guard let string,
167	              let data = string.data(using: .utf8),
168	              let jsonDictionary = try? JSONSerialization.jsonObject(with: data, options: .mutableContainers),
169	              let jsonData = try? JSONSerialization.data(withJSONObject: jsonDictionary, options: [.prettyPrinted]) else {
170	            return nil
171	        }
